    const updateSelection=()=>{const label=panel.querySelector('[data-govern-selected]'),button=panel.querySelector('[data-action="apply-govern-bulk"]');if(label)label.textContent=`已选择 ${governanceSelection.size} 条`;if(button)button.disabled=!governanceSelection.size;};
    const applyBatch=async(candidate_ids,category_ids,overwrite_manual,status)=>{if(!category_ids.length){alert('请先选择目标细类');return;}status.textContent='正在计算影响范围…';try{const impact=await data('/product-ingestion/taxonomy/candidates/categories/preview',jsonBody({candidate_ids,category_ids,overwrite_manual})),brandSummary=impact.brands.slice(0,5).map(item=>`${item.brand_name} ${item.count} 条`).join('，'),sample=impact.sample.slice(0,5).map(item=>`#${item.id} ${item.product_name}`).join('；'),message=`将更新 ${impact.affected_candidates} 条候选；跳过人工分类 ${impact.skipped_manual} 条，跳过不可处理 ${impact.skipped_unavailable} 条。${brandSummary?`\n品牌：${brandSummary}`:''}${sample?`\n样例：${sample}`:''}\n\n确认应用？`;if(!impact.affected_candidates){status.textContent='没有可更新的候选';return;}if(!confirm(message)){status.textContent='已取消';return;}status.textContent='正在批量保存…';const result=await data('/product-ingestion/taxonomy/candidates/categories',{...jsonBody({candidate_ids,category_ids,overwrite_manual,confirmed:true,reason:'Web 分类治理列表处理'}),method:'PUT'});governanceSelection.clear();alert(`已更新 ${result.affected_candidates} 条；跳过人工分类 ${result.skipped_manual} 条。`);return taxonomyView();}catch(error){status.textContent=error.message;}};
    const filterForm=panel.querySelector('[data-govern-filters]');if(filterForm)filterForm.onsubmit=event=>{event.preventDefault();const form=new FormData(event.currentTarget);governanceFilters={issue_type:String(form.get('issue_type')||''),brand:String(form.get('brand')||''),q:String(form.get('q')||'')};governancePage=0;governanceSelection.clear();return taxonomyView();};
    panel.onchange=event=>{const check=event.target.closest('[data-govern-check]');if(check){const candidateId=Number(check.dataset.governCheck);check.checked?governanceSelection.add(candidateId):governanceSelection.delete(candidateId);return updateSelection();}if(event.target.matches('[data-govern-select-shown]')){for(const item of shown)event.target.checked?governanceSelection.add(item.id):governanceSelection.delete(item.id);panel.querySelectorAll('[data-govern-check]').forEach(input=>{input.checked=governanceSelection.has(Number(input.dataset.governCheck));});return updateSelection();}if(event.target.matches('[data-govern-select-filtered]')){for(const item of filtered)event.target.checked?governanceSelection.add(item.id):governanceSelection.delete(item.id);panel.querySelectorAll('[data-govern-check]').forEach(input=>{input.checked=governanceSelection.has(Number(input.dataset.governCheck));});return updateSelection();}};
