    layer.innerHTML=`<section class="ingestion-modal-dialog ingestion-material-onboarding" role="dialog" aria-modal="true"><div><span class="ingestion-eyebrow">修正抽样</span><h3>样品哪里不对？</h3><p>请选择最接近的原因，系统会保留已有正确数据。</p></div><form data-material-sample-feedback class="ingestion-form"><div class="wide ingestion-option-grid">${[['wrong_page','官网材料页选错了'],['not_upholstery','这些不是布料、皮革或软包色板'],['mixed_content','混入了产品、木材、石材或其他内容'],['missing_materials','漏掉了页面里的布料、皮革或色板'],['field_mapping','名称、编号、分类、成分或色板对应错误'],['text_only','材料文字正确，但官网没有逐项色板'],['other','其他问题']].map(([value,label],index)=>`<label class="ingestion-option"><input type="radio" name="reason" value="${value}" ${index===0?'checked':''}><span>${label}</span></label>`).join('')}</div><label class="wide">补充说明（可选）<textarea name="note" maxlength="500" rows="3" placeholder="例如：没有看到色板图案；应继续进入每个材料系列。"></textarea></label><div class="wide ingestion-note">${handlingNote}</div><div class="wide ingestion-actions"><button type="button" data-back-material-sample>返回看样品</button><button type="button" data-change-material-page>改选官网材料页</button><button class="primary" type="submit">提交原因并继续处理</button></div><span class="wide" data-material-onboarding-status></span></form></section>`;
    const changePage=async()=>{const status=layer.querySelector('[data-material-onboarding-status]');status.textContent='正在返回材料页选择…';const next=await materialOnboardingDialog({sourceId:result.source.id,sourceUrl:'',previousSourceUrl:result.catalog.source_url,rediscover:true,message:'请填写更准确的官网材料页，或留空让系统重新寻找。'});if(next)layer.remove();};
