        <div class="ingestion-library-overview"><div><span>品牌</span><strong>${esc(brand?.brand_name||'暂无')}</strong></div><div><span>材料实体</span><strong>${brand?.material_count||0}</strong></div><div><span>色板已归档</span><strong>${brand?.swatch_count||0}</strong></div><div><span>产品声明页</span><strong>${relation.product_count||0}</strong></div><div><span>规则状态</span><strong>${esc(catalog?.status==='frozen'?'已冻结':catalog?.status||'未配置')}</strong></div></div>
